    if (live(own, "consumables")) parts.push_back(::lanesim::items::consumables::stats(s.consumables, own, ctx));
    if (live(own, "starters")) parts.push_back(::lanesim::items::starters::stats(s.starters, own, ctx));
    if (live(own, "spellblade")) parts.push_back(::lanesim::items::spellblade::stats(s.spellblade, own, ctx));
    if (live(own, "hydra")) parts.push_back(::lanesim::items::hydra::stats(s.hydra, own, ctx));
    if (live(own, "fighter")) parts.push_back(::lanesim::items::fighter::stats(s.fighter, own, ctx));
    if (live(own, "defense")) parts.push_back(::lanesim::items::defense::stats(s.defense, own, ctx));
