Effects active(ItemEffectState& s, const Owned& own, const Ctx& ctx, const Units& u, const Arr<int32_t>& request,
               ActiveOut& out) {
    size_t c = ctx.unit.size();
    out.used.assign(c, 0), out.cast_time.assign(c, 0.f), out.can_move.assign(c, 1), out.attack_reset.assign(c, 0);
    Effects eff_all = no_effects((int)c, (int)u.x.size());
    if (live(own, "consumables")) {
        auto [st, eff, r] = ::lanesim::items::consumables::active(s.consumables, own, ctx, u, request);
        s.consumables = st;
        merge_into(eff_all, eff);
        for (size_t h = 0; h < c; ++h) {
            if (r.used[h]) out.cast_time[h] = r.cast_time[h], out.can_move[h] = r.can_move[h];
            out.used[h] = out.used[h] | r.used[h], out.attack_reset[h] = out.attack_reset[h] | r.attack_reset[h];
        }
    }
    if (live(own, "hydra")) {
        auto [st, eff, r] = ::lanesim::items::hydra::active(s.hydra, own, ctx, u, request);
        s.hydra = st;
        merge_into(eff_all, eff);
        for (size_t h = 0; h < c; ++h) {
            if (r.used[h]) out.cast_time[h] = r.cast_time[h], out.can_move[h] = r.can_move[h];
            out.used[h] = out.used[h] | r.used[h], out.attack_reset[h] = out.attack_reset[h] | r.attack_reset[h];
        }
    }
    if (live(own, "actives")) {
        auto [st, eff, r] = ::lanesim::items::actives::active(s.actives, own, ctx, u, request);
        s.actives = st;
        merge_into(eff_all, eff);
        for (size_t h = 0; h < c; ++h) {
            if (r.used[h]) out.cast_time[h] = r.cast_time[h], out.can_move[h] = r.can_move[h];
            out.used[h] = out.used[h] | r.used[h], out.attack_reset[h] = out.attack_reset[h] | r.attack_reset[h];
        }
    }
    return eff_all;
}

